CREATE DATABASE IF NOT EXISTS wms DEFAULT CHARACTER SET utf8mb4;
CREATE DATABASE IF NOT EXISTS crm_scm DEFAULT CHARACTER SET utf8mb4;
DROP TABLE IF EXISTS wms.shipment;
CREATE TABLE wms.shipment (shipment_no VARCHAR(14) PRIMARY KEY, ref_po_no VARCHAR(14), vendor_code VARCHAR(12), transport_mode VARCHAR(8), forwarder VARCHAR(40), etd DATE, eta DATE, atd DATE, ata DATE, ship_status VARCHAR(16), delay_days INT, delay_reason VARCHAR(120), bl_no VARCHAR(20)) ENGINE=InnoDB;
DROP TABLE IF EXISTS wms.stock_daily;
CREATE TABLE wms.stock_daily (snapshot_date DATE, sku_code VARCHAR(12), warehouse_cd VARCHAR(10), on_hand_qty INT, reserved_qty INT, in_transit_qty INT, avg_daily_usage DECIMAL(10,2)) ENGINE=InnoDB;
DROP TABLE IF EXISTS crm_scm.customer;
CREATE TABLE crm_scm.customer (cust_no VARCHAR(12) PRIMARY KEY, cust_name VARCHAR(80), country VARCHAR(30), segment VARCHAR(30), incoterms VARCHAR(5), payment_terms VARCHAR(20), sla_days INT) ENGINE=InnoDB;
DROP TABLE IF EXISTS crm_scm.sales_order;
CREATE TABLE crm_scm.sales_order (so_no VARCHAR(14) PRIMARY KEY, cust_no VARCHAR(12), sku_code VARCHAR(12), order_date DATE, requested_date DATE, confirmed_date DATE, qty INT, so_status VARCHAR(14), risk_note VARCHAR(160)) ENGINE=InnoDB;
DROP TABLE IF EXISTS crm_scm.claim_ticket;
CREATE TABLE crm_scm.claim_ticket (ticket_no VARCHAR(14) PRIMARY KEY, cust_no VARCHAR(12), so_no VARCHAR(14), sku_code VARCHAR(12), opened_date DATE, category VARCHAR(20), severity VARCHAR(8), ticket_status VARCHAR(12), root_cause VARCHAR(160), ref_po_no VARCHAR(14), ref_shipment_no VARCHAR(14)) ENGINE=InnoDB;
